    static void refresh(MainActivity a){
        if(a.tools==null||a.canvas==null)return;if(a.colorPresets!=null)a.colorPresets.refresh();
        ArrayList<String> order=ToolSettings.visible(a);
        a.canvas.paletteTools(ToolSettings.panelOrder(order));
        a.canvas.cycleTools=order.stream().filter(s->!s.equals("eraser")&&!GuideTools.auxiliary(s)).toArray(String[]::new);
        boolean guides=a.toolsTab.equals("guides");String signature=a.toolsTab+":"+String.join(",",order);
        if(!signature.equals(a.tools.getTag())){
            a.tools.removeAllViews();a.tools.setTag(signature);if(a.tools instanceof ToolStrip)((ToolStrip)a.tools).placed=false;
            if(guides)GuideStudio.populate(a);
            else {
                Icons hand=a.icon("hand","Навигация",()->a.canvas.setTool("hand"));hand.tint=Studio.MUTED;a.tools.addView(hand,new LinearLayout.LayoutParams(a.dp(40),a.dp(48)));
                for(String tool:order){if(tool.equals("hand"))continue;ToolArt.Tile tile=new ToolArt.Tile(a,tool);tile.setOnClickListener(v->{if(a.canvas.tool.equals(tool))ToolStudio.options(a,tool);else a.canvas.setTool(tool);});tile.setOnLongClickListener(v->{ToolStudio.options(a,tool);return true;});a.tools.addView(tile,new LinearLayout.LayoutParams(a.dp(43),a.dp(64)));}
                View divider=new View(a);divider.setBackgroundColor(Studio.LINE);LinearLayout.LayoutParams dl=new LinearLayout.LayoutParams(a.dp(1),a.dp(26));dl.setMargins(a.dp(8),0,a.dp(8),0);a.tools.addView(divider,dl);
                TextView width=a.text("",12,Studio.TEXT,true);width.setTag("width");a.pad(width,9,15);width.setOnClickListener(v->a.widthDialog());a.tools.addView(width);a.addIcon(a.tools,"plus","Настроить инструменты",a::toolbarDialog);a.addIcon(a.tools,"more","Все инструменты",()->ToolStudio.gallery(a));
            }
            if(a.tools.getParent() instanceof HorizontalScrollView)((HorizontalScrollView)a.tools.getParent()).scrollTo(0,0);
        }
        String selected=guides?GuideStudio.selected(a.canvas):a.canvas.tool;
        for(int i=0;i<a.tools.getChildCount();i++){
            View child=a.tools.getChildAt(i);
            if("ink-color".equals(child.getTag())){child.setEnabled(a.canvas.canColor());child.setAlpha(a.canvas.canColor()?1:.28f);}
            if(child.isClickable())ToolbarMotion.press(a,child);
            if(child instanceof ToolArt.Tile)((ToolArt.Tile)child).select(((ToolArt.Tile)child).tool.equals(selected));
            else if(child instanceof TextView){if("width".equals(child.getTag()))((TextView)child).setText(String.format(Locale.ROOT,"%.1f",a.canvas.tool.equals("eraser")?a.canvas.eraserWidth:a.canvas.width));else if("guide-ink".equals(child.getTag()))((TextView)child).setText(Ink.label(a.canvas.tool)+"  ›");}
            child.invalidate();
        }
        if(a.tools instanceof ToolStrip)((ToolStrip)a.tools).select(selected);GuideStudio.updateTabs(a);history(a);
    }
    static void history(MainActivity a){if(a.canvas==null||a.body==null)return;for(View view:a.chrome)if(view instanceof LinearLayout){LinearLayout row=(LinearLayout)view;for(int i=0;i<row.getChildCount();i++){View v=row.getChildAt(i);boolean undo="undo".equals(v.getTag()),redo="redo".equals(v.getTag());if(undo||redo){boolean enabled=undo?a.canvas.history().canUndo():a.canvas.history().canRedo();v.setEnabled(enabled);v.setAlpha(enabled?1:.32f);}}}}
